package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class MoveEffectChecks {
 private GameWorld world(GameWorld.Skill skill){GameWorld w=new GameWorld();w.enemies.clear();w.spikes.clear();TestWorlds.equip(w,skill);w.setDropSeed(2);return w;}
 private GameWorld.Enemy target(GameWorld w,float x,int hp){GameWorld.Enemy e=new GameWorld.Enemy(x,112,true);e.hp=e.maxHp=hp;e.primaryType=GameWorld.Element.NORMAL;e.timer=10000;w.enemies.add(e);return e;}
 private void tick(GameWorld w,int frames){for(int n=0;n<frames;n++)w.step(1f/60,0,false,false);}
 @Test public void everySkillUsesStatsAndSharedDamageFormula(){for(int level:new int[]{1,20,40}){GameWorld w=world(GameWorld.Skill.SCRATCH);w.level=level;for(GameWorld.Skill move:GameWorld.Skill.values()){int expected=move.category==GameWorld.Category.STATUS?0:PokemonStats.damage(level,move.power==0?40:move.power,move.category==GameWorld.Category.PHYSICAL?w.stats().attack:w.stats().specialAttack,w.referenceDefense());assertEquals(move.name,expected,w.skillDamage(move));}}assertTrue(GameWorld.Skill.FANG.cooldown<GameWorld.Skill.FLARE_BLITZ.cooldown);}
 @Test public void tierMembershipMatchesRequestedGroups(){GameWorld.Item[][] groups={{GameWorld.Item.WIDE},{GameWorld.Item.MULTI,GameWorld.Item.SASH,GameWorld.Item.LEFTOVERS,GameWorld.Item.SCOPE,GameWorld.Item.TM},{GameWorld.Item.MUSCLE,GameWorld.Item.EGG,GameWorld.Item.GLASSES,GameWorld.Item.CLAW,GameWorld.Item.SHELL},{GameWorld.Item.CHARCOAL,GameWorld.Item.BELT,GameWorld.Item.FANG,GameWorld.Item.SCARF},{GameWorld.Item.BERRY,GameWorld.Item.CANDY}};int count=0;for(int i=0;i<groups.length;i++)for(GameWorld.Item item:groups[i]){assertEquals(item.title,i+1,item.tier);count++;}assertEquals(GameWorld.Item.values().length,count);}
 @Test public void flameChargeDashesBoostsSpeedOnHitAndNeverAutomaticallyBurns(){GameWorld w=world(GameWorld.Skill.FLAME_CHARGE);GameWorld.Enemy e=target(w,195,5000);assertTrue(w.trySkill(0));tick(w,35);assertTrue(w.x>220);assertFalse(w.dashing());assertEquals(1,w.speedStage);assertEquals((230+w.stats().speed*1.4f)*1.15f,w.movementSpeed(),.01);assertEquals(0,e.burnTime,0);assertEquals(6,w.hp);}
 @Test public void flameChargeMissDoesNotBoostSpeed(){GameWorld w=world(GameWorld.Skill.FLAME_CHARGE);w.trySkill(0);tick(w,35);assertEquals(0,w.speedStage);assertEquals(6,w.hp);}
 @Test public void flameChargeBoostsAfterKoAndOnlyOnceWithEchoes(){GameWorld w=world(GameWorld.Skill.FLAME_CHARGE);target(w,195,1);w.trySkill(0);tick(w,35);assertEquals(1,w.kills);assertEquals(1,w.speedStage);w=world(GameWorld.Skill.FLAME_CHARGE);target(w,195,5000);target(w,260,5000);w.collectItem(GameWorld.Item.MULTI);w.collectItem(GameWorld.Item.MULTI);w.trySkill(0);tick(w,45);assertEquals(1,w.speedStage);}
 @Test public void flareBlitzMissHasNoRecoilAndRealHitsHaveNormalizedRecoil(){GameWorld w=world(GameWorld.Skill.FLARE_BLITZ);w.trySkill(0);tick(w,50);assertEquals(6,w.hp);w=world(GameWorld.Skill.FLARE_BLITZ);w.level=20;w.evolution=1;w.maxHp=w.hp=8;target(w,195,65);w.invulnerable=100;w.trySkill(0);tick(w,50);assertEquals(6,w.hp);assertEquals(1,w.kills);assertTrue(w.itemNotice.contains("반동"));}
 @Test public void recoilCanFaintAndDoesNotConsumeFocusSash(){GameWorld w=world(GameWorld.Skill.FLARE_BLITZ);w.level=20;w.evolution=1;w.maxHp=8;w.hp=1;w.collectItem(GameWorld.Item.SASH);target(w,195,65);w.trySkill(0);tick(w,50);assertEquals(0,w.hp);assertEquals(1,w.itemCount(GameWorld.Item.SASH));}
 @Test public void immuneDashDoesNotCauseRecoil(){GameWorld w=world(GameWorld.Skill.TAKE_DOWN);GameWorld.Enemy e=target(w,195,5000);e.primaryType=GameWorld.Element.GHOST;w.trySkill(0);tick(w,35);assertEquals(6,w.hp);assertEquals(5000,e.hp);}
 @Test public void metalClawAndCrunchUseMetadataStatEffects(){GameWorld w=world(GameWorld.Skill.METAL_CLAW);target(w,195,5000);w.trySkill(0);tick(w,35);assertEquals(1,w.attackStage);w=world(GameWorld.Skill.CRUNCH);GameWorld.Enemy e=target(w,195,5000);w.trySkill(0);tick(w,35);assertEquals(-1,e.defenseStage);int hp=e.hp;TestWorlds.equip(w,GameWorld.Skill.SCRATCH);w.skillCooldowns[0]=0;w.trySkill(0);tick(w,35);assertEquals(5,hp-e.hp);}
 @Test public void overheatDropsSpecialAttackOnceEvenWithEchoes(){GameWorld w=world(GameWorld.Skill.OVERHEAT);target(w,195,5000);w.collectItem(GameWorld.Item.MULTI);w.collectItem(GameWorld.Item.MULTI);int before=w.skillDamage(GameWorld.Skill.OVERHEAT);w.trySkill(0);tick(w,35);assertEquals(-2,w.specialAttackStage);assertEquals(Math.round(before*.5f),w.skillDamage(GameWorld.Skill.OVERHEAT));}
 @Test public void burnChanceIsProbabilisticRatherThanEveryFireHit(){GameWorld w=world(GameWorld.Skill.EMBER);GameWorld.Enemy e=target(w,195,5000);int burns=0;for(int n=0;n<300;n++){w.skillCooldowns[0]=0;w.hitStop=0;e.hp=5000;e.burnTime=0;assertTrue(w.trySkill(0));tick(w,35);if(e.burnTime>0)burns++;}assertTrue("burns="+burns,burns>15&&burns<50);}
 @Test public void weatherBallSnapshotsSunnyTypeAndPowerIntoProjectile(){GameWorld w=world(GameWorld.Skill.WEATHER_BALL);GameWorld.Enemy e=target(w,400,5000);e.primaryType=GameWorld.Element.FIRE;assertEquals(4,w.skillDamage(GameWorld.Skill.WEATHER_BALL));w.fireBuff=10;assertEquals(GameWorld.Element.FIRE,w.skillElement(GameWorld.Skill.WEATHER_BALL));assertEquals(11,w.skillDamage(GameWorld.Skill.WEATHER_BALL));w.trySkill(0);tick(w,12);assertEquals(GameWorld.Element.FIRE,w.skillShots.get(0).element);w.fireBuff=0;tick(w,45);assertEquals(4996,e.hp);assertEquals(0,e.burnTime,0);}
 @Test public void temperFlareDoublesAfterAnAttackMiss(){GameWorld w=world(GameWorld.Skill.SCRATCH);w.trySkill(0);tick(w,35);TestWorlds.equip(w,GameWorld.Skill.TEMPER_FLARE);w.skillCooldowns[0]=0;GameWorld.Enemy e=target(w,195,5000);w.trySkill(0);tick(w,35);assertEquals(4990,e.hp);}
 @Test public void dashStopsAtWallWithoutTeleporting(){GameWorld w=world(GameWorld.Skill.FLAME_CHARGE);w.blocks.clear();w.blocks.add(new GameWorld.Block(0,0,4500,112));w.blocks.add(new GameWorld.Block(180,112,40,200));w.trySkill(0);float old=w.x;for(int n=0;n<35;n++){w.step(1f/60,0,false,false);assertTrue(Math.abs(w.x-old)<12);old=w.x;}assertEquals(136,w.x,.01);assertFalse(w.dashing());assertEquals(0,w.speedStage);}
 @Test public void pauseFreezesDashAndRestartClearsAbilityStages(){GameWorld w=world(GameWorld.Skill.FLAME_CHARGE);target(w,195,5000);w.trySkill(0);tick(w,14);assertTrue(w.dashing());w.paused=true;float x=w.x,cd=w.skillCooldowns[0];tick(w,120);assertEquals(x,w.x,0);assertEquals(cd,w.skillCooldowns[0],0);w.paused=false;tick(w,35);assertEquals(1,w.speedStage);w.restart();assertEquals(0,w.speedStage);assertFalse(w.dashing());}
 @Test public void allProfilesAndDescriptionsExist(){for(GameWorld.Skill move:GameWorld.Skill.values()){assertNotNull(move.name,MoveEffects.profile(move));assertFalse(move.description().isEmpty());}assertEquals(100,MoveEffects.profile(GameWorld.Skill.FLAME_CHARGE).statChance);assertEquals(10,MoveEffects.profile(GameWorld.Skill.FLARE_BLITZ).chance);assertEquals(30,MoveEffects.profile(GameWorld.Skill.ROCK_SLIDE).flinch);}
}
